tileidx_t tile_wall_coloured(tileidx_t idx, int col)
{
    int num_pairs = sizeof(wall_colour_pairs) / sizeof(wall_colour_pairs[0]);
    tile_variation key(idx, col);
    tileidx_t found;
    bool result = binary_search<tile_variation, tileidx_t>(
       key, &wall_colour_pairs[0], num_pairs,
       &tile_variation::cmp, &found);
    return (result ? found : idx);
}

static _variation_pair wall_enchant_pairs[] =
{
    _variation_pair(tile_variation(0, 0), 0),
};

tileidx_t tile_wall_enchanted(tileidx_t idx, int ench)
{
    int num_pairs = sizeof(wall_enchant_pairs) / sizeof(wall_enchant_pairs[0]);
    tile_variation key(idx, ench);
    tileidx_t found;
    bool result = binary_search<tile_variation, tileidx_t>(
       key, &wall_enchant_pairs[0], num_pairs,
       &tile_variation::cmp, &found);
    return (result ? found : idx);
}

